import sys,pathlib,json,collections,statistics,math
sys.path.insert(0,str(pathlib.Path(__file__).resolve().parents[1]/'python'))
from common import *
index=json.loads((ROOT/'results/solver_comparison/current_run.json').read_text());p=ROOT/index['path'];rows=[json.loads(s) for s in (p/'conditional_solver_results.jsonl').read_text().splitlines()];summary=[]
for work in WORKS:
 for radius in [1,2]:
  rr=[r for r in rows if r['workload']==work and r['radius']==radius]
  for fam in ['HUF','LSD0','LSD2','OSD0','OSD2','BEAM16']:
   selected=[(r,[c for c in r['candidates'] if c['family']==fam]) for r in rr];selected=[(r,c) for r,c in selected if c]
   if not selected:continue
   summary.append(dict(workload=work,radius=radius,family=fam,n_systems=len(selected),correct_class_in_set=sum(any(c['correct_logical_class'] for c in cc) for r,cc in selected),correct_class_min_cost=sum(min(cc,key=lambda c:c['configuration_cost'])['correct_logical_class'] for r,cc in selected),lower_cost_correct_class=sum(any(c['correct_logical_class'] and c['configuration_cost']<r['incumbent_cost']-1e-10 for c in cc) for r,cc in selected),mean_distinct_classes=statistics.mean(len({tuple(c['logical_signature']) for c in cc}) for r,cc in selected),mean_min_cost=statistics.mean(min(c['configuration_cost'] for c in cc) for r,cc in selected),mean_solve_ms=statistics.mean(cc[0].get('native_solve_ns',cc[0].get('reference_beam_total_ns'))/1e6 for r,cc in selected)))
lines=['# Conditioned inner-solver comparison','',f"Run `{index['path']}`; {len(rows)} identical conditioned systems from the P0 exploratory diagnostic corpus. Each problem freezes the same exterior correction, D_J z = D_J x_J and original prior weights. No generator/solver receives truth. True logical-class membership is evaluated offline after candidate generation.",'','| Workload | Radius | Solver | Systems | Correct class in set | Lowest-cost choice correct | Cheaper correct witness | Mean classes | Mean solve ms |','|---|---:|---|---:|---:|---:|---:|---:|---:|']
for r in summary:lines.append(f"| {r['workload']} | {r['radius']} | {r['family']} | {r['n_systems']} | {r['correct_class_in_set']} | {r['correct_class_min_cost']} | {r['lower_cost_correct_class']} | {r['mean_distinct_classes']:.3g} | {r['mean_solve_ms']:.4g} |")
lines+=['','HUF/LSD/OSD times are native local solve only, excluding model preparation, bindings, audit extraction and logical scoring. BEAM16 is a bounded **offline Python research prototype**, with its full reference search time; these scopes are not an end-to-end speed comparison. OSD2 is predeclared deferred above 2,500 conditioned fault variables, not marked defeated. Exact configuration-cost CP-SAT results and real-cost bounds are stored per problem; no unknown optimum is replaced by the best observed cost.','','The beam examines a model-only pool of at most 128 exact detector-kernel moves, preserving independent logical directions where the limit permits. Width K=16 and depth2 bound generated attempts by 1+128*(1+16). It reserves half the retained slots for distinct logical signatures and fills the rest by configuration cost. This deliberately biased candidate-set coverage is not posterior sampling or exact MAP.','','Candidate-set recovery and lowest-cost selection differ materially on surface problems: the beam can contain the correct logical class without the cheapest configuration being in that class. BB144 stronger-solver proposals can be correct yet fail strict descent. Thus a cost-only larger search cannot be assumed to improve logical accuracy. These enriched diagnostic outcomes do not select the deployed policy; fresh independent validation will compare native BP/solver changes and only then bounded candidate/selection variants.','','All returned candidates passed D_J z=t_J. The unchanged original native decoder remains the regression baseline. Native multi-candidate code must reproduce the reference beam on tractable fixtures and pass sanitizers/reset/order checks before timing.']
atomic(p/'summary.json',summary);(ROOT/'results/SOLVER_COMPARISON.md').write_text('\n'.join(lines)+'\n');ledger('P1 conditional solver report','COMPLETE',systems=len(rows))
